#include <stdio.h>
#include <string.h>
#include <sys/stat.h>

int main(void) {
    printf("hello, world\n");
    struct stat st;
    stat("/proc/self/exe", &st);
    printf("executable: %ld bytes\n", (long)st.st_size);
    /* list each shared library mapped into this process once */
    FILE *f = fopen("/proc/self/maps", "r");
    char line[512], last[256] = "";
    while (fgets(line, sizeof line, f)) {
        char *path = strchr(line, '/');
        if (path && strstr(path, ".so") && strcmp(path, last)) {
            printf("mapped: %s", path);
            strncpy(last, path, sizeof last - 1);
        }
    }
    return 0;
}

