#include <stdio.h>
#include <string.h>

int main(void) {
    unsigned char u = 255;
    u = u + 1;                          /* unsigned: wraps modulo 256 */
    printf("255 + 1 in a byte = %d\n", u);

    signed char c = -12;
    printf("-12 as a byte     = 0x%02hhx\n", c);
    int widened = c;                    /* sign extension to 32 bits */
    printf("same value as int = 0x%08x = %d\n", widened, widened);

    int x = 42;                         /* 0x0000002a */
    unsigned char b[4];
    memcpy(b, &x, 4);                   /* look at the raw bytes */
    printf("bytes of 42 in memory: %02x %02x %02x %02x\n",
           b[0], b[1], b[2], b[3]);

    printf("0.1 + 0.2 = %.17g\n", 0.1 + 0.2);
    return 0;
}

