#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define N (1 << 20)
static int data[N];

static int cmp(const void *a, const void *b) {
    return *(const int *)a - *(const int *)b;
}

__attribute__((noinline)) long sum_big(const int *a, long n) {
    long s = 0;
    for (long i = 0; i < n; i++)
        if (a[i] >= 128)          /* the branch we care about */
            s += a[i];
    return s;
}

static double ns_per_element(void) {
    struct timespec t0, t1;
    long s = 0;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (int rep = 0; rep < 20; rep++)
        { s += sum_big(data, N); __asm__ volatile("" ::: "memory"); }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    if (s == 42) puts("");        /* keep s alive */
    return ((t1.tv_sec - t0.tv_sec) * 1e9 + (t1.tv_nsec - t0.tv_nsec)) / (20.0 * N);
}

int main(void) {
    srand(1);
    for (long i = 0; i < N; i++) data[i] = rand() % 256;
    printf("random order: %.2f ns per element\n", ns_per_element());
    qsort(data, N, sizeof data[0], cmp);
    printf("sorted order: %.2f ns per element\n", ns_per_element());
    return 0;
}
